<template>
<section class="semi-panel" v-loading="loading">
 <div class="semi-heading"><strong>{{raw?'原料加工进度与工单关闭':'半成品流转与工单关闭'}}</strong><el-button :disabled="loading||busy" @click="load">刷新</el-button><el-button v-if="active&&has('metal:work-order:partial-close')" type="warning" :disabled="busy||loading" @click="open('close')">部分完工关闭</el-button><el-button v-if="data?.workOrder.status==='CLOSED_PARTIAL'&&has('metal:work-order:reopen')" :disabled="busy||loading" @click="open('reopen')">撤销部分关闭</el-button></div>
 <p v-if="failed||refreshFailed" role="alert">流转资料更新失败，当前显示可能过期，请刷新重试。</p>
 <template v-if="data">
 <p v-if="raw" class="semi-help">原料加工按计划投入、实际投入和产出净重核对，各工序分别确认阶段闭合。关闭保留真实加工记录与实物来源。</p><p v-else class="semi-help">半成品还库只恢复原库存，不自动释放。新工单正常完成后，系统按策略核对并自动释放适用余量；历史工单和部分关闭仍需单独确认。有效释放后的余量可供同厂、同客户且路线匹配的其他工单领用。</p>
 <template v-if="data.progress?.length"><h4>{{raw?'原料工序进度':'工序数量覆盖'}}</h4><el-table :data="data.progress" border><el-table-column prop="processName" label="工序"/><el-table-column label="产出阶段"><template #default="{row}">{{row.outputStage==='RAW'?'前处理原料':row.outputStage==='FINISHED'?'最终成品':row.outputStage==='SEMI'?'中间半成品':'历史未记录'}}</template></el-table-column><el-table-column label="计量方式"><template #default="{row}">{{raw||row.outputStage==='RAW'||row.measurementMode==='WEIGHT'?'按重量':'按件'}}</template></el-table-column><el-table-column :label="raw?'产出净重(g)':'本单加工'"><template #default="{row}">{{raw?decimalText(row.outputWeight):row.outputStage==='RAW'||row.measurementMode==='WEIGHT'?decimalText(row.outputWeight)+'g':row.localQuantity+'件'}}</template></el-table-column><el-table-column :label="raw?'阶段闭合':'重量工序状态'" min-width="200"><template #default="{row}"><template v-if="raw||row.outputStage==='RAW'||row.measurementMode==='WEIGHT'">{{row.weightStageClosed?'已结束投产':row.routeCovered?'外部来源已覆盖':'可继续分批投产'}}<el-button v-if="active&&has(row.weightStageClosed?'metal:work-order:reopen':'metal:process-batch:settle')" link type="primary" :disabled="busy" @click="open(row.weightStageClosed?'stageReopen':'stageClose',row)">{{row.weightStageClosed?'重新投产':'结束投产'}}</el-button></template><span v-else>—</span></template></el-table-column><el-table-column v-if="!raw" label="外部半成品接入(件)"><template #default="{row}">{{row.outputStage==='RAW'||row.measurementMode==='WEIGHT'?'—':row.externalQuantity}}</template></el-table-column><el-table-column v-if="!raw" label="许可跳过(件)"><template #default="{row}">{{row.outputStage==='RAW'||row.measurementMode==='WEIGHT'?'—':row.skippedQuantity}}</template></el-table-column><el-table-column v-if="!raw" label="数量覆盖合计(件)"><template #default="{row}">{{row.outputStage==='RAW'||row.measurementMode==='WEIGHT'?'—':row.coveredQuantity}}</template></el-table-column></el-table></template>
 <template v-if="data.items?.length"><h4>{{raw?'原料投入计划与阶段状态':'产品完成情况'}}</h4><el-table :data="data.items" border><el-table-column :label="raw?'物料':'产品'"><template #default="{row}">{{productName(row)}}</template></el-table-column><el-table-column v-if="raw" label="物料编码"><template #default="{row}">{{snapshot(row).code||'—'}}</template></el-table-column><el-table-column v-if="raw" label="计划投入净重(g)"><template #default="{row}">{{decimalText(row.plannedInputWeight)}}</template></el-table-column><el-table-column v-if="raw" label="已投入净重(g)"><template #default="{row}">{{decimalText(row.committedInputWeight)}}</template></el-table-column><el-table-column v-if="raw" label="阶段闭合"><template #default="{row}">{{itemStage(row)}}</template></el-table-column><el-table-column v-if="!raw" prop="plannedQuantity" label="原计划(件)"/><el-table-column v-if="!raw" prop="completedQuantity" label="最终已结算完成(件)"/><el-table-column v-if="!raw" prop="cancelledQuantity" :label="data.workOrder.status==='CLOSED_PARTIAL'?'取消继续加工(件)':'尚未完成(件)'"/></el-table></template>
 <template v-if="data.stocks?.length"><h4>剩余原料／半成品库存</h4><el-table :data="data.stocks" border><el-table-column label="物料／产品"><template #default="{row}">{{row.category==='RAW'?'原料 · ':''}}{{row.name}}</template></el-table-column><el-table-column prop="processName" label="已完成工序"/><el-table-column prop="batchNo" label="来源批次" min-width="180"/><el-table-column label="实物库存(件)"><template #default="{row}">{{row.category==='RAW'||row.measurementMode==='WEIGHT'?'—':row.quantity}}</template></el-table-column><el-table-column prop="netWeight" label="实物净重(g)" :formatter="decimalColumn"/><el-table-column label="参考件数（选填）" min-width="150"><template #default="{row}">{{row.category==='RAW'||row.measurementMode!=='WEIGHT'?'—':row.referenceComplete===false?'未完整记录':row.referenceQuantity??'未记录'}}</template></el-table-column><el-table-column label="已释放未领(件)"><template #default="{row}">{{row.category==='RAW'||row.measurementMode==='WEIGHT'?'—':row.releasedQuantity}}</template></el-table-column><el-table-column label="尚未释放(件)"><template #default="{row}">{{row.category==='RAW'||row.measurementMode==='WEIGHT'?'—':row.unreleasedQuantity}}</template></el-table-column><el-table-column v-if="has('metal:semi-release:add')" label="操作" width="90"><template #default="{row}"><el-button v-if="row.category!=='RAW'&&closed&&has('metal:semi-release:add')&&(row.measurementMode==='WEIGHT'?Number(row.unreleasedWeight)>0:Number(row.unreleasedQuantity)>0)" size="small" type="primary" :disabled="busy" @click="open('release',row)">释放</el-button></template></el-table-column></el-table></template>
 <template v-if="!raw&&data.releases?.length"><h4>释放记录</h4><el-table :data="data.releases" border><el-table-column prop="releaseId" label="释放记录"/><el-table-column label="物料／产品"><template #default="{row}">{{row.category==='RAW'?'原料 · ':''}}{{row.name}}</template></el-table-column><el-table-column label="释放(件)"><template #default="{row}">{{row.category==='RAW'||row.measurementMode==='WEIGHT'?'—':row.quantity}}</template></el-table-column><el-table-column prop="netWeight" label="释放净重(g)" :formatter="decimalColumn"/><el-table-column label="可领(件)"><template #default="{row}">{{row.measurementMode==='WEIGHT'?'—':row.availableQuantity}}</template></el-table-column><el-table-column prop="availableWeight" label="可领净重(g)" :formatter="decimalColumn"/><el-table-column label="状态"><template #default="{row}">{{row.status==='ACTIVE'?'有效':'已撤销'}}</template></el-table-column><el-table-column v-if="has('metal:semi-release:cancel')" label="操作"><template #default="{row}"><el-button v-if="row.status==='ACTIVE'&&has('metal:semi-release:cancel')" size="small" :disabled="busy" @click="open('cancel',row)">撤销释放</el-button></template></el-table-column></el-table></template>
 <template v-if="!raw&&data.uses?.length"><h4>跨工单来源与去向</h4><el-table :data="data.uses" border><el-table-column prop="releaseId" label="来源释放记录"/><el-table-column prop="orderNo" label="生产出库单"/><el-table-column prop="targetWorkOrderNo" label="领用工单"/><el-table-column label="原领用(件)"><template #default="{row}">{{row.category==='RAW'||row.measurementMode==='WEIGHT'?'—':row.quantity}}</template></el-table-column><el-table-column prop="netWeight" label="原领用净重(g)" :formatter="decimalColumn"/><el-table-column prop="status" label="单据状态"/></el-table></template>
 <template v-if="data.closures?.length"><h4>关闭操作记录</h4><el-table :data="data.closures" border><el-table-column prop="createTime" label="时间"/><el-table-column label="操作"><template #default="{row}">{{row.action==='CLOSE'?'部分完工关闭':'撤销部分关闭'}}</template></el-table-column><el-table-column prop="reason" label="原因"/></el-table></template>
 </template>
 <el-dialog v-model="visible" :title="title" width="min(900px,96vw)" :close-on-click-modal="false" :close-on-press-escape="!busy&&!uncertain" :show-close="!busy&&!uncertain" :before-close="beforeClose" append-to-body>
 <el-form ref="flowForm" :model="draft" :rules="rules" scroll-to-error label-width="120px" :disabled="busy||uncertain" v-if="data&&target">
  <template v-if="mode==='close'"><el-table :data="data.items" border><el-table-column :label="raw?'物料':'产品'"><template #default="{row}">{{productName(row)}}</template></el-table-column><el-table-column v-if="raw" label="物料编码"><template #default="{row}">{{snapshot(row).code||'—'}}</template></el-table-column><el-table-column v-if="raw" label="计划投入净重(g)"><template #default="{row}">{{decimalText(row.plannedInputWeight)}}</template></el-table-column><el-table-column v-if="raw" label="已投入净重(g)"><template #default="{row}">{{decimalText(row.committedInputWeight)}}</template></el-table-column><el-table-column v-if="raw" label="阶段闭合"><template #default="{row}">{{itemStage(row)}}</template></el-table-column><el-table-column v-if="!raw" prop="plannedQuantity" label="计划(件)"/><el-table-column v-if="!raw" prop="completedQuantity" label="实际完成(件)"/><el-table-column v-if="!raw" prop="cancelledQuantity" label="取消继续加工(件)"/></el-table><p>{{raw?'关闭保留各工序真实投入、产出与损耗。请先处理所有未结算批次并核对阶段状态。':'关闭保留各工序真实加工记录，不补造完成数量。请先处理所有未结算批次。'}}</p><el-checkbox v-model="draft.confirmed" :disabled="busy">{{raw?'已核对实物余料与全部加工批次':'已核对实物余料，已领未加工半成品已还库'}}</el-checkbox></template>
  <template v-if="mode==='release'"><el-alert :closable="false" type="info" title="还库不会自动释放；本次释放不增加实物库存，原来源与历史损耗保持不变。"/><p>释放后可供同厂、同客户且工序匹配的其他工单领用。</p><p>可释放：{{target.unreleasedQuantity}}件 / {{decimalText(target.unreleasedWeight)}}g</p><div><el-form-item v-if="target.measurementMode!=='WEIGHT'" label="释放件数" prop="quantity" :rules="[requiredRule('释放件数',true,false),...([])]"><el-input v-model="draft.quantity" @input="v=>quantityInput=String(v)" inputmode="numeric"/></el-form-item><el-form-item v-if="target.measurementMode==='WEIGHT'" label="参考件数（选填）" prop="referenceQuantity"><el-input v-model="draft.referenceQuantity" inputmode="numeric" placeholder="仅作记录，不占用释放额度"/></el-form-item><el-form-item label="释放净重(g)" prop="netWeight" :rules="[requiredRule('释放净重(g)',true,false),...([])]"><BusinessDecimalInput v-model="draft.netWeight" inputmode="decimal"/></el-form-item></div></template>
  <template v-if="mode==='stageClose'||mode==='stageReopen'"><p>{{raw?'本操作变更原料工序的投产状态。请先完成各批次还料与结算；存在下游依赖时不能重新投产。':'本操作变更整道重量工序的投产状态，不补造完成件数。请先完成各批次还料与结算；存在下游依赖时不能重新投产。'}}</p><el-checkbox v-model="draft.confirmed">全部批次及实物已核对</el-checkbox></template>
  <p v-if="mode==='cancel'">仅尚未被有效领用的释放记录可以撤销，不改变实物库存。</p><p v-if="mode==='reopen'">请先撤销有效释放，存在下游领用依赖时不能重新打开。</p>
  <el-form-item label="操作原因" prop="reason" :rules="[requiredRule('操作原因',true,false),...([])]"><el-input v-model="draft.reason" type="textarea" placeholder="填写操作原因" maxlength="500" show-word-limit :disabled="busy"/></el-form-item>
 </el-form>
 <el-alert v-if="needsReload" title="资料已变化，请关闭后重新加载并核对，当前输入已保留" type="warning" :closable="false"/><el-alert v-if="uncertain" title="提交结果待确认，已保留原请求与输入，请重试原请求" type="warning" :closable="false"/><template #footer><el-button :disabled="busy||uncertain" @click="visible=false">取消</el-button><el-button v-if="has(modePermission)" type="primary" :loading="busy" :disabled="!target||needsReload" @click="save">{{uncertain?'重试原请求':'确认'}}</el-button></template>
 </el-dialog>
</section>
</template>
<script setup lang="ts">
import BusinessDecimalInput from '@/components/BusinessDecimalInput.vue'

import {decimalText,decimalColumn,businessValue} from '@/utils/business-decimal'

import {getToken} from '@/utils/auth'
import {useInventoryRefresh,type InventoryRefreshContext} from '@/composables/useInventoryRefresh'
import {onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {requiredRule} from '@/utils/input-validation'
import type {FormInstance} from 'element-plus'
import {fieldRule,textRules,integerError,decimalError,applyFieldErrors} from '@/utils/input-validation'
import { useActionPermission } from '@/composables/useActionPermission'
const actionPermission = useActionPermission()
import {ref,reactive,computed,watch,onBeforeUnmount} from 'vue'
import {ElMessage} from 'element-plus'
import useUserStore from '@/store/modules/user'
import {semiFlowOverview,semiFlowAction,type Row} from '@/api/metal/warehouse'
import {createUUID} from '@/utils/uuid'
const props=defineProps<{workOrderId:string}>(),emit=defineEmits(['changed']),user=useUserStore()
const has=(p:string)=>actionPermission.has(p)
const modePermission=computed(()=>({close:'metal:work-order:partial-close',reopen:'metal:work-order:reopen',release:'metal:semi-release:add',cancel:'metal:semi-release:cancel',stageClose:'metal:process-batch:settle',stageReopen:'metal:work-order:reopen'}[mode.value]||''))
const data=ref<Row>(),loading=ref(false),failed=ref(false),busy=ref(false),visible=ref(false),target=ref<Row>(),mode=ref(''),needsReload=ref(false),uncertain=ref(false)
const draft=reactive<Row>({}),title=computed(()=>({close:'部分完工关闭',reopen:'撤销部分关闭',release:'释放剩余半成品',cancel:'撤销释放',stageClose:'重量工序结束投产',stageReopen:'重量工序重新投产'}[mode.value]||''))
const active=computed(()=>['WAITING_MATERIAL','IN_PROGRESS'].includes(data.value?.workOrder.status)),closed=computed(()=>['COMPLETED','CLOSED_PARTIAL'].includes(data.value?.workOrder.status))
const raw=computed(()=>data.value?.workOrder.taskType==='RAW_PROCESSING')
const flowForm=ref<FormInstance>(),quantityInput=ref<string>()
const rules={referenceQuantity:[fieldRule(v=>v==null||v===''?'':integerError(v,'参考件数'))],reason:textRules('操作原因',500,true),quantity:[fieldRule(v=>integerError(quantityInput.value??v,'释放件数'))],netWeight:[fieldRule(v=>decimalError(v,'释放净重',{positive:true}))]}
let epoch=0,dialogEpoch=0,disposed=false,openedVersion=0,openedSnapshot='',attempt:{url:string;body:Row}|undefined
function snapshot(row:Row):Row{const value=raw.value?(row.materialSnapshot??row.material_snapshot):row.productSnapshot;try{return typeof value==='string'?JSON.parse(value):value??{}}catch{return {}}}
function productName(row:Row){return snapshot(row).name||(raw.value?'原料':'产品')}
function itemStage(row:Row){const stages=(data.value?.progress??[]).filter((step:Row)=>String(step.itemId)===String(row.itemId));return !stages.length?'尚未开始':stages.every((step:Row)=>step.weightStageClosed||step.routeCovered)?'阶段已闭合':'阶段尚未闭合'}
const canRead=()=>has('metal:work-order:query')&&!!user.token&&user.token===getToken()
function resetAccess(){epoch++;dialogEpoch++;data.value=undefined;loading.value=false;failed.value=false;visible.value=false;target.value=undefined;busy.value=false;uncertain.value=false;needsReload.value=false;attempt=undefined}
async function load(){if(busy.value||uncertain.value)return false;return readOverview(false)}
async function readOverview(background:boolean,context?:InventoryRefreshContext){if(!canRead()){resetAccess();return false}if(loading.value)return false;const session=user.token,account=String(user.id),round=++epoch,work=props.workOrderId,valid=()=>!disposed&&canRead()&&session===user.token&&account===String(user.id)&&epoch===round&&work===props.workOrderId,current=()=>valid()&&(!context||context.isCurrent()&&!busy.value&&!uncertain.value);loading.value=true;if(!background){failed.value=false;data.value=undefined}try{const r=await semiFlowOverview(work,current,background);if(!current())return false;if(!r.data?.workOrder)throw Error('invalid context');data.value=r.data;failed.value=false;return true}catch{if(current())failed.value=true;return false}finally{if(valid())loading.value=false}}
async function probe(context:InventoryRefreshContext){const work=props.workOrderId,round=dialogEpoch,current=()=>context.isCurrent()&&canRead()&&visible.value&&!busy.value&&!uncertain.value&&work===props.workOrderId&&round===dialogEpoch;const r=await semiFlowOverview(work,current,true);if(current()&&JSON.stringify(r.data)!==openedSnapshot)needsReload.value=true}
const {failed:refreshFailed,invalidate:invalidateRefresh}=useInventoryRefresh(context=>readOverview(true,context),computed(()=>visible.value),{allowed:canRead,reset:resetAccess},{probe,paused:computed(()=>loading.value||busy.value||uncertain.value)})
function open(action:string,row?:Row){if(!canRead()){resetAccess();return}quantityInput.value=undefined;flowForm.value?.clearValidate();if(busy.value||uncertain.value||loading.value||!data.value)return;dialogEpoch++;mode.value=action;target.value=JSON.parse(JSON.stringify(row||data.value.workOrder));openedVersion=data.value.workOrder.version;openedSnapshot=JSON.stringify(data.value);needsReload.value=false;attempt=undefined;Object.keys(draft).forEach(k=>delete draft[k]);Object.assign(draft,{requestId:createUUID(),reason:'',confirmed:false,quantity:row?.unreleasedQuantity,netWeight:row?.unreleasedWeight});visible.value=true}
function beforeClose(done:()=>void){if(!busy.value&&!uncertain.value)done()}
async function save(){if(!canRead()){resetAccess();return}if(!has(modePermission.value)||busy.value||!visible.value||needsReload.value)return;if(uncertain.value&&attempt){await submitAttempt(attempt);return}const validationRound=dialogEpoch;const valid=await flowForm.value?.validate().catch(()=>false);if(!canRead()){resetAccess();return}if(!valid||validationRound!==dialogEpoch||!visible.value||needsReload.value||!has(modePermission.value))return;if(mode.value==='release'){draft.quantity=target.value?.measurementMode==='WEIGHT'?null:Number(draft.quantity);draft.referenceQuantity=draft.referenceQuantity==null||draft.referenceQuantity===''?null:Number(draft.referenceQuantity)};if(busy.value||!target.value||!draft.reason?.trim()){ElMessage.error('请填写操作原因');return}if(mode.value==='close'&&!draft.confirmed){ElMessage.error('请先核对并确认实物余料');return}if(mode.value==='release'&&((target.value?.measurementMode!=='WEIGHT'&&(!Number.isInteger(draft.quantity)||draft.quantity<1))||!/^\d+(\.\d{1,6})?$/.test(String(draft.netWeight))||Number(draft.netWeight)<=0)){ElMessage.error('请填写正整数件数和最多6位小数的正净重');return}
 const work=props.workOrderId,selected=JSON.parse(JSON.stringify(target.value)),action=mode.value,body=JSON.parse(JSON.stringify({...draft,version:action.startsWith('stage')?openedVersion:selected.version}));
 const url=action.startsWith('stage')?`/metal/work-order/${work}/weight-stage/${selected.itemId}/${selected.processId}/${action==='stageClose'?'close':'reopen'}`:action==='close'||action==='reopen'?'/metal/work-order/'+work+'/'+(action==='close'?'partial-close':'reopen'):action==='release'?'/metal/warehouse/inventory/'+selected.inventoryId+'/semi-release':'/metal/warehouse/semi-release/'+selected.releaseId+'/cancel';attempt={url,body};await submitAttempt(attempt)
}
async function submitAttempt(value:{url:string;body:Row}){const session=user.token,account=String(user.id),work=props.workOrderId,round=dialogEpoch,current=()=>!disposed&&canRead()&&session===user.token&&account===String(user.id)&&work===props.workOrderId&&round===dialogEpoch&&has(modePermission.value);busy.value=true;try{await semiFlowAction(value.url,value.body,current);if(!current())return;uncertain.value=false;attempt=undefined;visible.value=false;busy.value=false;ElMessage.success('操作成功');emit('changed');invalidateRefresh()}catch(error:any){if(current()){uncertain.value=!!error?.isAxiosError&&(!error.response||error.response.status>=500);if(/版本|重新加载|刷新/.test(error?.message??''))needsReload.value=true;applyFieldErrors(flowForm.value,error)}}finally{if(current())busy.value=false}}
watch(visible,v=>{if(!v&&!busy.value){dialogEpoch++;target.value=undefined}})
watch(()=>props.workOrderId,()=>{resetAccess();void load()},{immediate:true,flush:'sync'})
onBeforeRouteLeave(()=>{if(busy.value||uncertain.value)return false});onBeforeRouteUpdate(()=>{if(busy.value||uncertain.value)return false})
onBeforeUnmount(()=>{disposed=true;epoch++;dialogEpoch++;visible.value=false;target.value=undefined})
</script>
<style scoped>
.semi-panel{margin:16px 0;padding:16px;background:white;border:1px solid #e8ebf0;border-radius:8px;min-width:0}.semi-heading{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.semi-help{color:#606266;line-height:1.7}.semi-panel h4{margin:20px 0 10px}.semi-panel :deep(.el-table){width:100%}.semi-panel :deep(.cell){overflow-wrap:anywhere} @media(max-width:480px){.semi-panel{padding:10px}.semi-heading{gap:8px}}
</style>

<style scoped>.semi-panel :deep(th.el-table__cell),.semi-panel :deep(td.el-table__cell){text-align:center}</style>
